(12220, '_transient_tablepress_72a06d5f3d5a992b2629584f9e2bffef', '<h2 class=\"tablepress-table-name tablepress-table-name-id-1\">Past Presidents and Officers</h2>\n\n<table id=\"tablepress-1\" class=\"tablepress tablepress-id-1\">\n<thead>\n<tr class=\"row-1\">\n	<th class=\"column-1\">Year</th><th class=\"column-2\">President</th><th class=\"column-3\">Deputy President</th><th class=\"column-4\">Secretary General</th>\n</tr>\n</thead>\n<tbody class=\"row-hover\">\n<tr class=\"row-2\">\n	<td class=\"column-1\">1993 - 1996</td><td class=\"column-2\">Teruaki Kataoka</td><td class=\"column-3\">-</td><td class=\"column-4\">Norihisa Maeda</td>\n</tr>\n<tr class=\"row-3\">\n	<td class=\"column-1\">1997 - 2000</td><td class=\"column-2\">David Russell, QC</td><td class=\"column-3\">-</td><td class=\"column-4\">Peter Cowdroy</td>\n</tr>\n<tr class=\"row-4\">\n	<td class=\"column-1\">2001 - 2004</td><td class=\"column-2\">Koo, Jong-Tae</td><td class=\"column-3\">Ahmad Mustapha Ghazali</td><td class=\"column-4\">Lee Yong-Ro, Chang Luck</td>\n</tr>\n<tr class=\"row-5\">\n	<td class=\"column-1\">2005 - 2008</td><td class=\"column-2\">Kinjiro Mori</td><td class=\"column-3\">Gil Levy</td><td class=\"column-4\">Hirotaka Ishii</td>\n</tr>\n<tr class=\"row-6\">\n	<td class=\"column-1\">2009 - 2012</td><td class=\"column-2\">Gil Levy</td><td class=\"column-3\">Thomas Lee</td><td class=\"column-4\">Noel Rowland</td>\n</tr>\n<tr class=\"row-7\">\n	<td class=\"column-1\">2013 - 2014</td><td class=\"column-2\">Thomas Lee</td><td class=\"column-3\">Toshihiro Ikeda</td><td class=\"column-4\">Noel Rowland</td>\n</tr>\n<tr class=\"row-8\">\n	<td class=\"column-1\">2015 - Present</td><td class=\"column-2\">Toshihiro Ikeda</td><td class=\"column-3\">Chung Ku-Chung<br />\nEuney Marie Mata Perez</td><td class=\"column-4\">Katsuzo Nakamura</td>\n</tr>\n</tbody>\n</table>\n', 'no'),
