(6817, 5777, '_themify_builder_settings_json', '[{\"row_order\":\"0\",\"gutter\":\"gutter-default\",\"equal_column_height\":\"\",\"column_alignment\":\"col_align_top\",\"cols\":[{\"column_order\":\"0\",\"grid_class\":\"col-full first last\",\"grid_width\":\"\",\"modules\":{\"1\":{\"mod_name\":\"text\",\"mod_settings\":{\"content_text\":\"<p><strong>Our Story<\\/strong><\\/p>\",\"text_user_role\":\"|\",\"background_image-type\":\"image\",\"background_image-type_image\":\"image\",\"background_image-type_gradient\":\"gradient\",\"background_image-gradient-type\":\"linear\",\"background_image-gradient-angle\":\"180\",\"background_image-gradient\":\"0% rgb(0, 0, 0)|100% rgb(255, 255, 255)\",\"background_image-css\":\"background-image: -moz-linear-gradient(180deg,rgb(0, 0, 0) 0%, rgb(255, 255, 255) 100%);\\nbackground-image: -webkit-linear-gradient(180deg,rgb(0, 0, 0) 0%, rgb(255, 255, 255) 100%);\\nbackground-image: -o-linear-gradient(180deg,rgb(0, 0, 0) 0%, rgb(255, 255, 255) 100%);\\nbackground-image: -ms-linear-gradient(180deg,rgb(0, 0, 0) 0%, rgb(255, 255, 255) 100%);\\nbackground-image: linear-gradient(180deg,rgb(0, 0, 0) 0%, rgb(255, 255, 255) 100%);\\n\",\"font_family\":\"Roboto\",\"font_color\":\"26378b_1.00\",\"font_size\":\"30\",\"font_size_unit\":\"px\",\"line_height_unit\":\"px\",\"text_align\":\"center\",\"text_align_left\":\"left\",\"text_align_center\":\"center\",\"text_align_right\":\"right\",\"text_align_justify\":\"justify\",\"padding_top_unit\":\"px\",\"padding_right_unit\":\"px\",\"padding_bottom_unit\":\"px\",\"padding_left_unit\":\"px\",\"checkbox_padding_apply_all\":\"padding\",\"checkbox_padding_apply_all_padding\":\"padding\",\"margin_top_unit\":\"px\",\"margin_right_unit\":\"px\",\"margin_bottom_unit\":\"px\",\"margin_left_unit\":\"px\",\"checkbox_margin_apply_all\":\"margin\",\"checkbox_margin_apply_all_margin\":\"margin\",\"border_top_style\":\"solid\",\"border_right_style\":\"solid\",\"border_bottom_style\":\"solid\",\"border_left_style\":\"s