(8137, 6085, 'image', '5727'),
(8138, 6085, '_image', 'field_59478460a8eaf'),
(8139, 6085, 'name', 'Toshihiro Ikeda'),
(8140, 6085, '_name', 'field_5947847da8eb0'),
(8141, 6085, 'position', 'President'),
(8142, 6085, '_position', 'field_59478486a8eb1'),
(8143, 6085, 'professional_status', '<ul>\r\n   <li>Spent many years working in the Inland Revenue Department of Hong Kong Government, specializing in tax disputes resolution, tax litigations, tax investigations and prosecutions for offences under the Inland Revenue Ordinance (IRO), last position as senior assessor (1976 to 1993)</li>\r\n  <li>Partner and Head of Tax, Trust and Corporate Services of a Hong Kong CPA firm belonging to a second tier international accountancy network (1998 – 2002)</li>\r\n   <li>Specialist in international and cross border taxation, wealth succession planning, civil tax litigations, and pre-IPO and corporate finance related structuring and advisory work involving Mainland China, Hong Kong and overseas operations</li>\r\n</ul>'),
(8144, 6085, '_professional_status', 'field_59478491a8eb2'),
(8145, 6085, 'memberships', '<ul>\r\n   <li>FCPA, Hong Kong Institute of Certified Public Accountants, 1989</li>\r\n  <li>Fellow, Association of Chartered Certified Accountants (UK), 1984</li>\r\n  <li>Member, Chartered Institute of Secretaries and Administrators (UK), 1981</li>\r\n   <li>Member, The Hong Kong Institute of Chartered Secretaries, 1994</li>\r\n</ul>'),
(8146, 6085, '_memberships', 'field_594784a3a8eb3'),
(8147, 6085, 'academic_background', '<ul>\r\n   <li>Higher Diploma in Accountancy, Hong Kong Polytechnic University, 1976</li>\r\n  <li>Bachelor of Laws, University of London, UK, 1988</li>\r\n</ul>'),
(8148, 6085, '_academic_background', 'field_594784c9a8eb4'),
